Because the optimization \eqref{eq:OnlOptProb} is feasible at time step $k{=}0$ and $t_0 {\ge} 0$, the applied input $u_0 = \hat{u}_{0|0}^*$  satisfies  
\begin{align}\label{eq:RecFeasproof}
    F x_0 + G u_0 \le b - t_0\le b.
\end{align}
Therefore, \eqref{eq:Constraints} is satisfied at time $k{=}0$. Moreover, because RF is satisfied, 
 the optimization \eqref{eq:OnlOptProb} always remains feasible under the MPC control law $\pi(x)$. By using a similar argument as the one presented above for $k{=}0$,  \eqref{eq:Constraints} is satisfied for all $k{\ge} 0$.

\label{Thm:NecSuff}
The closed loop system \eqref{eq:Dynamics}-\eqref{eq:OnlOptProb} satisfies SRF  if, and only if, for all $ \mathbf{s}_k {\in} \mathbb{P}_0$, $w_k{\in}\mathcal{W}$, and $ j{\in} \mathbb{N}_{1}^{n_\Delta}$, there exist $ \hat{\mathbf{u}}_{k+1}^j $ such that 
\begin{align}\label{eq:NecSuff}
     \mathbf{H}_{xu}  \left(\mathbf{C}^j_{\mathbf{s}} \mathbf{s}_k + \mathbf{C}^j_{\mathbf{w}} w_k + \mathbf{S_u}\hat{\mathbf{u}}_{k+1}^j \right)  \leq \mathbf{b}-\mathbf{t}, &
\end{align}
where $\mathbf{C}^j_{\mathbf{s}} = \mathbf{L} + \mathbf{S}_x B_p \Delta^j  D_{xu}$, and  $\mathbf{C}^j_{\mathbf{w}} = \mathbf{S}_x (B_w  + B_p \Delta^j D_w)$.

\label{Thm:SuffCond}
    Consider the polytopes $\mathbb{P}_1$ and $\{\mathbb{P}_2^j\}_{j=1}^{n_{\Delta}}$  proposed in \eqref{eq:Poytope_P1_P2j}. Then, the closed loop \eqref{eq:Dynamics}-\eqref{eq:OnlOptProb} satisfies SRF if there exist feedback gains $\{K^j\}_{j=1}^{n_\Delta}$, $\{ \{M_i^j\}_{j=i}^{n_{\Delta}} \}_{i=0}^{N-1}$ and $\{ \{ K_{i,\Delta}^j\}_{j=i}^{n_{\Delta}}\}_{i=0}^{N-1} $  such that
\begin{align}\label{eq:SuffCond}
     \mathbb{P}_1 \subseteq \mathbb{P}_2^j, \quad \forall j \in \mathbb{N}_1^{n_{\Delta}}.
\end{align}

For \eqref{eq:OnlOptProb} to be strongly recursively feasible, \eqref{eq:FeasCond_k+1} must be satisfied for every $\begin{bmatrix}
        \mathbf{s}_k ^\intercal & w_k^\intercal
    \end{bmatrix}^\intercal \in \mathbb{P}_1$ and $\Delta_k \in \mathcal{P}$. 

Let $\Delta_k $ be defined as in \eqref{eq:Delta_k} and a candidate control input sequence be defined as $\hat{\mathbf{u}}_{k+1} =  \sum_{j=1}^{n_\Delta} \tau_j \hat{\mathbf{u}}_{k+1}^j$, where $\hat{\mathbf{u}}_{k+1}^j$ are parameterized according to \eqref{eq:InputParameterization}. 
Substituting the candidate sequence in \eqref{eq:s_k+1}, 
\begin{subequations}\label{eq:SuffCondPf1}
\begin{align}
    &\mathbf{S} \mathbf{s}_{k+1} = (\mathbf{L} {+} \mathbf{S}_x B_p \sum_{j=1}^{n_\Delta} \tau_j \Delta^j  D_{xu}  ) \mathbf{s}_k  \nonumber \\
     & {+} \mathbf{S}_x (B_w {+} B_p \sum_{j=1}^{n_\Delta} \tau_j\Delta^j D_w )w_k  +\mathbf{S}_u  \sum_{j=1}^{n_\Delta} \tau_j \hat{\mathbf{u}}_{k+1}^j \label{eq:SuffCondPf1_1}\\
     &= \sum_{j=1}^{n_\Delta} \tau_j \bigg( \bigg( \mathbf{L}_K^j + \mathbf{S}_x B_p \Delta^j  D_{xu}  \nonumber\\ 
     &\quad + \mathbf{S}_u \mathbf{K}^j_{\Delta} \begin{bmatrix}
        I_{n_x+n_u}  & 0_{n_x+n_u, n_u(N-1)}
    \end{bmatrix}\bigg) \mathbf{s}_k \nonumber \\     
    & \quad + \textbf{S}_x \big( B_w + B_p\Delta^jD_w \big) w_k + \mathbf{S}_u\mathbf{M}^j B_w w_k
        \bigg) \label{eq:SuffCondPf1_2}\\
        & = \sum_{j=1}^{n_\Delta} \tau_j \bigg(\mathbf{C}_K^j \mathbf{s}_k + \mathbf{C}_M^j w_k  \bigg) . \label{eq:SuffCondPf1_3}
\end{align}
\end{subequations}
In \eqref{eq:SuffCondPf1}, \eqref{eq:SuffCondPf1_2} is obtained by substituting the control law \eqref{eq:InputParameterization} in \eqref{eq:SuffCondPf1_1} and using the definition of $\mathbf{L}_K^j$. Using \eqref{eq:SuffCondPf1}, it can be seen that
\begin{subequations}\label{eq:SuffCondPf2}
\begin{align}
   & H_{xu} \mathbf{S} \mathbf{s}_{k+1} = H_{xu}  \sum_{j=1}^{n_\Delta} \tau_j \bigg(\mathbf{C}_K^j \mathbf{s}_k + \mathbf{C}_M^j w_k  \bigg) \label{eq:SuffCondPf2_1}\\
   &=    \sum_{j=1}^{n_\Delta} \tau_j H_{xu} \big( \mathbf{C}_K^j \mathbf{s}_k + \mathbf{C}_M^j w_k  \big) \label{eq:SuffCondPf2_2}\\
   &\le  \sum_{j=1}^{n_\Delta} \tau_j (\mathbf{b}-\mathbf{t}) \le \mathbf{b}-\mathbf{t}, \label{eq:SuffCondPf2_3}
\end{align}
\end{subequations}
where \eqref{eq:SuffCondPf2_3} is obtained because any $\begin{bmatrix}
        \mathbf{s}_k ^\intercal & w_k^\intercal
    \end{bmatrix}^\intercal $ inside $ \mathbb{P}_1$ also lies inside $\mathbb{P}_2^j$ from \eqref{eq:SuffCond}. 
Therefore, \eqref{eq:FeasCond_k+1} is satisfied for all feasible realizations of $\mathbf{s}_k$, $\Delta_k$ and $w_k$ under the proposed feedback if \eqref{eq:SuffCond} holds, and so the closed loop \eqref{eq:Dynamics}-\eqref{eq:OnlOptProb} satisfies SRF.

\cite[Lemma~5.6]{kouvaritakis2015model}\label{Lem:Farkas}
    Let $\mathbb{X}_i = \Set{x}{H_i x \le h_i}$ for $i=1,2$ be two polytopes. Then, $\mathbb{X}_1 \subseteq \mathbb{X}_2 $ is satisfied if, and only if, there exists a matrix $\Lambda$ such that
    \begin{align}\label{eq:Farkas}
       \Lambda \ge 0, \quad \Lambda H_1 = H_2, \quad \Lambda h_1 \le h_2.
    \end{align}

\label{Prop:LambdaRefo}
The set inclusions \eqref{eq:SuffCond} are satisfied if, and only if, there exist matrices $\{ \Lambda^j\}_{j=1}^{n_{\Delta}}$ such that 
    \begin{subequations}\label{eq:LambdaRefo}
    \begin{align}
        \Lambda^j \ge 0, \quad
    \Lambda^j &\begin{bmatrix}
        \mathbf{b}-\mathbf{t} \\ h_w
    \end{bmatrix} \le \mathbf{b}-\mathbf{t},
    \label{eq:LambdaRefo_1}\\
        \Lambda^j \begin{bmatrix}
        \mathbf{H}_{xu}\mathbf{S} & 0 \\
        0 & H_w
    \end{bmatrix} &= \mathbf{H}_{xu}\begin{bmatrix}
        \mathbf{C}_K^j &   \mathbf{C}_M^j
    \end{bmatrix},  \: \: \forall j \in \mathbb{N}_{1}^{n_{\Delta}}. \label{eq:LambdaRefo_2}
    \end{align}
    \end{subequations}

Consider the system \eqref{eq:Dynamics}-\eqref{eq:wBound} and a compact set $\mathbb{X}\subseteq \mathbb{R}^{n_x}$ including the origin as an interior point. A function $V:\mathbb{R}^n \rightarrow \mathbb{R}_{\ge 0}$ is called an ISS Lyapunov function in $\mathbb{X}$ with respect to $w_k$ if there exist $\mathcal{K}_{\infty}$ functions $\sigma_1 (\cdot),\sigma_2(\cdot),\sigma_3(\cdot)$ and a $\mathcal{K}$ function $\lambda_2(\cdot)$ such that $\forall x_k \in \mathbb{X}$
    \begin{subequations}\label{eq:ISSLyap}
    \begin{align}
    \sigma_1(\left\| x_k \right\|) \le V(x_k) &\le \sigma_2(\left\| x_k \right\|), \label{eq:ISSLyap1} \\
    V(x_{k+1}) - V(x_k)  &\le -\sigma_3(\left\| x_k \right\|) + \lambda_2(w_k).\label{eq:ISSLyap2}
    \end{align}
    \end{subequations}

\label{Thm:Props}
    Let the offline optimization problem \eqref{eq:OfflineOpt} be feasible, the cost function satisfy \eqref{eq:TermCostLyap}, and the online optimization \eqref{eq:OnlOptProb_reg} have a feasible solution at time $k=0$. Moreover, let $\mathbb{P}_{0,x}$ be the projection of $\mathbb{P}_0$ on the first $n_x$ elements of $\mathbf{s}_k$, and let the origin be an interior point of $\mathbb{P}_{0,x}$. Then, the closed loop formed by a system with dynamics \eqref{eq:Dynamics}-\eqref{eq:wBound} and the robust MPC controller in Algorithm \ref{Alg:RMPC} satisfies the following properties:
    \begin{enumerate}[label=(\alph*)]
        \item The problem \eqref{eq:OnlOptProb_reg} remains feasible for all $k > 0$. \label{Thm:Props1}
        \item The constraints \eqref{eq:Constraints} are satisfied for all $k > 0$.\label{Thm:Props2}
        \item The closed-loop system is ISS in $\mathbb{P}_{0,x}$ with respect to $w_k$.\label{Thm:Props3}
    \end{enumerate}

In order to prove property \ref{Thm:Props1}, note that the constraints in Proposition \ref{Prop:LambdaRefo} are satisfied because the offline optimization \eqref{eq:OfflineOpt} is feasible. Therefore, the set inclusions  \eqref{eq:SuffCond} are satisfied, and Theorem \ref{Thm:SuffCond} implies that the online MPC optimization \eqref{eq:OnlOptProb_reg} is strongly recursively feasible.  Moreover, because \eqref{eq:OnlOptProb_reg} admits a feasible solution at time $k=0$, it remains feasible for all $k > 0$. 

    The property \ref{Thm:Props2} follows from Theorem \ref{Th:RF_RCS}. This is because the offline optimization \eqref{eq:OfflineOpt} explicitly enforces $t_0 \ge 0$, and SRF implies RF. 

    The proof of \ref{Thm:Props3} can be seen as follows. Let the optimal MPC cost function be a candidate ISS Lyapunov function denoted by
    \begin{align}\label{eq:CompactCost}
    \begin{split}
        V(x_k) &= \hat{x}_{N|k}^{*\intercal} Q_N \hat{x}_{N|k}^* + \displaystyle \sum_{i=0}^{N-1} \left( \hat{x}_{i|k}^{*\intercal} Q_x \hat{x}_{i|k}^* +  \hat{u}_{i|k}^{*\intercal} Q_u \hat{u}_{i|k}^* \right) \\
        &= \mathbf{s}_k^{*\intercal} \mathbf{S}^\intercal  Q_s \mathbf{S} \mathbf{s}_k^*.
    \end{split}
    \end{align}

    In the following, it will be shown that $V(x)$ satisfies \eqref{eq:ISSLyap}.  Consider  $\sigma_1(\left\| x \right\|) = \rho_{\min} (Q_x) \left\| x \right\|^2$, which is guaranteed to be a lower bound of $V(x)$. Moreover, $V(x)$ is a continuous and piecewise quadratic function in  $\mathbb{P}_{0,x}$ as shown in \cite{bemporad2002explicit}. Therefore, the existence of $\sigma_2(\cdot)$ satisfying \eqref{eq:ISSLyap1} is a direct consequence of \cite[Lemma~4]{limon2009input}.

    In order to show \eqref{eq:ISSLyap2}, let the perturbation $\Delta_k$ be given as \eqref{eq:Delta_k} and consider the candidate input sequences in \eqref{eq:InputParameterization}. The cost function satisfies
    \begin{subequations}\label{eq:Lyapunov}
    \begin{align}
        &V(x_{k+1}) - V(x_k) = \mathbf{s}_{k+1}^{*\intercal} \mathbf{S}^\intercal  Q_s \mathbf{S} \mathbf{s}_{k+1}^* - \mathbf{s}_k^{*\intercal} \mathbf{S}^\intercal  Q_s \mathbf{S} \mathbf{s}_k^* \nonumber \\
        &\le \sum_{j=1}^{n_\Delta} \tau_j \bigg(\mathbf{C}_K^j \mathbf{s}_k^* + \mathbf{C}_M^j w_k  \bigg)^\intercal  Q_s \sum_{l=1}^{n_\Delta} \tau_l \bigg(\mathbf{C}_K^l \mathbf{s}_k^* + \mathbf{C}_M^l w_k  \bigg)\nonumber \\
        & \qquad \qquad - \mathbf{s}_k^{*\intercal} \mathbf{S}^\intercal  Q_s \mathbf{S} \mathbf{s}_k^* \label{eq:Lyapunov1}\\
        &\le  \left(1+\frac{1}{\epsilon}\right) \left(w_k^\intercal \mathbf{C}_M(\tau)^\intercal Q_s \mathbf{C}_M(\tau) w_k \right) + \nonumber\\ 
        & \quad (1+\epsilon) \left(\mathbf{s}_k^{*\intercal} \mathbf{C}_K(\tau)^\intercal  Q_s \mathbf{C}_K(\tau) \mathbf{s}_k^* \right) - \mathbf{s}_k^{*\intercal} \mathbf{S}^\intercal  Q_s \mathbf{S} \mathbf{s}_k^* \label{eq:Lyapunov2} \\
        &\le \lambda_2(w_k) + \mathbf{s}_k^{*\intercal} ( (1+\epsilon) \mathbf{C}_K(\tau)^\intercal  Q_s \mathbf{C}_K(\tau)  - \mathbf{S}^\intercal  Q_s \mathbf{S} )\mathbf{s}_k^* \label{eq:Lyapunov3}
    \end{align}
    \end{subequations}
     where $\mathbf{C}_K(\tau) := \sum_{j=1}^{n_\Delta} \tau_j\mathbf{C}_K^j $ and $\mathbf{C}_M(\tau) := \sum_{j=1}^{n_\Delta} \tau_j\mathbf{C}_M^j $, and \eqref{eq:Lyapunov2} is obtained by applying Cauchy-Schwarz theorem and Fenchel's inequality \cite{boyd2004convex}, by which, $\left\| x+w \right\| \le (1+\epsilon)\left\| x \right\| + (1+\frac{1}{\epsilon}) \left\| w \right\|$ for any $\epsilon>0$. The function $\lambda_2(w_k)$ in \eqref{eq:Lyapunov3} can chosen as the first term in \eqref{eq:Lyapunov2}. Moreover, using \eqref{eq:TermCostLyap}, it can be seen that 
     \begin{subequations}\label{eq:SchurTerm}
     \begin{align}
         &\mathbf{S}^\intercal  Q_s \mathbf{S} - P - (1{+}\epsilon)\mathbf{C}_K^{j\intercal}  Q_s \mathbf{C}_K^j  \succ 0, \quad \forall j \in \mathbb{N}_{1}^{n_\Delta} \label{eq:SchurTerm1}\\
         &\implies \begin{bmatrix}
             (1{+}\epsilon)^{-1}Q_s^{-1}  & \mathbf{C}_K^j \\
            \mathbf{C}_K^{j\intercal} & \mathbf{S}^\intercal  Q_s \mathbf{S} - P
         \end{bmatrix} \succ 0, \: \forall j \in \mathbb{N}_{1}^{n_\Delta}, \label{eq:SchurTerm2}\\
        &\implies  \begin{bmatrix}
            \displaystyle\sum_{j=1}^{n_\Delta} \tau_j (1{+}\epsilon)^{-1} Q_s^{-1}  & \displaystyle\sum_{j=1}^{n_\Delta} \tau_j \mathbf{C}_K^j \\
            \displaystyle\sum_{j=1}^{n_\Delta} \tau_j \mathbf{C}_K^{j\intercal} & \displaystyle\sum_{j=1}^{n_\Delta} \tau_j (\mathbf{S}^\intercal  Q_s \mathbf{S} - P)
         \end{bmatrix} \succ 0, \label{eq:SchurTerm3}\\
       &\implies  \begin{bmatrix}
             (1{+}\epsilon)^{-1}Q_s^{-1}  & \mathbf{C}_K(\tau) \\
            \mathbf{C}_K(\tau)^\intercal & (\mathbf{S}^\intercal  Q_s \mathbf{S}- P)
         \end{bmatrix}  \succ 0, \label{eq:SchurTerm4}\\
        &\implies  \mathbf{S}^\intercal  Q_s \mathbf{S}- P - (1{+}\epsilon)\mathbf{C}_K(\tau)^\intercal  Q_s \mathbf{C}_K(\tau)   \succ 0, \label{eq:SchurTerm5}
     \end{align}
     \end{subequations}
     where the Schur complement lemma \cite{zhang2006schur} is used to obtain \eqref{eq:SchurTerm2} and \eqref{eq:SchurTerm5}. Using \eqref{eq:Lyapunov3} and \eqref{eq:SchurTerm5},
\begin{align}
\begin{split}
    &V(x_{k+1}) - V(x_k) \le \lambda_2(w_k) - s_k^{*\intercal} P s_k^* \\
    &\le \lambda_2(w_k) - x_k^{\intercal}P_x x_k = \lambda_2(w_k) - \sigma_3(\left\| x_k \right\|). 
\end{split}
\end{align}
Thus, $V(x)$ satisfies \eqref{eq:ISSLyap}, and is an ISS Lyapunov function of the system. Therefore, applying \cite[Lemma~3.5]{jiang2001input}, the closed-loop system is ISS.

Because the optimization \eqref{eq:OnlOptProb} is feasible at time step $k=0$ and $t_0 \ge 0$, there exists $\hat{u}_{0,0}$ such that 
\begin{align}
    F x_0 + G \hat{u}_{0,0} \le b - t_0\le b.
\end{align}
Therefore, \eqref{eq:Constraints} is satisfied at time $k=0$. Moreover, because Assumption \ref{Ass:RecFeas} is satisfied, optimization \eqref{eq:OnlOptProb} always remains feasible under the MPC control law $\pi(x)$. Therefore,  \eqref{eq:Constraints} is satisfied for all $k\ge 0$.

\label{Thm:NecSuff}
    Let $\mathbb{P}_1$ be a polytope defined as
    \begin{equation}\label{eq:Poytope_P1}
    \mathbb{P}_1 = \Set*{\begin{bmatrix}
        \mathbf{s}_k \\ w_k
    \end{bmatrix} \: \: }{\: \:\begin{bmatrix}
        \mathbf{H}_{xu}\mathbf{S} & 0 \\
        0 & H_w
    \end{bmatrix}
    \begin{bmatrix}
        \mathbf{s}_k \\ w_k
    \end{bmatrix} \leq
    \begin{bmatrix}
        \mathbf{b}-\mathbf{t} \\ h_w
    \end{bmatrix} }.
\end{equation}
Then, SRF is satisfied if, and only if, $\forall$   $\begin{bmatrix}
        \mathbf{s}_k ^\intercal & w_k^\intercal
    \end{bmatrix}^\intercal \in \mathbb{P}_1$ and $ \forall j\in \mathbb{N}_{1}^{n_\Delta}$, there exist $ \hat{\mathbf{u}}_{k+1}^j $ such that 
\begin{align}\label{eq:NecSuff}
     \mathbf{H}_{xu}  \left(\mathbf{C}^{\Delta^j}_{\mathbf{s}} \mathbf{s}_k + \mathbf{C}^{\Delta^j}_{\mathbf{w}} w_k + \mathbf{S_u}\hat{\mathbf{u}}_{k+1}^j \right)  \leq \mathbf{b}-\mathbf{t}, &
\end{align}
where $\mathbf{C}^{\Delta^j}_{\mathbf{s}} = \mathbf{L} + \mathbf{S}_x B_p \Delta^j  D_{xu}$,   $\mathbf{C}^{\Delta^j}_{\mathbf{w}} = \mathbf{S}_x (B_w  + B_p \Delta^j D_w)$, and $\Delta^j$ denote the vertices of $\mathcal{P}$.

\textit{Sufficiency:}\\
Let $\hat{\mathbf{u}}_{k+1}^j$ be the input trajectory such that \eqref{eq:NecSuff} is satisfied for each $j \in \mathbb{N}_{1}^{n_\Delta}$ and  $\Big[\mathbf{s}_k ^\intercal ~ w_k^\intercal\Big] ^\intercal \in \mathbb{P}_1$. 
Let the true perturbation $\Delta_k$ and an input trajectory $\hat{\mathbf{u}}_{k+1}$ be given as 
\begin{align}\label{eq:Delta_k}
    \Delta_k = \sum_{j=1}^{n_\Delta} \mu_j \Delta^j,\quad \hat{\mathbf{u}}_{k+1} =  \sum_{j=1}^{n_\Delta} \tau_j \hat{\mathbf{u}}_{k+1}^j,
\end{align}
where $ \sum_{j=1}^{n_\Delta} \mu_j = 1$, $\mu_j \ge 0$, and $\tau_j\in\mathbb{R}$. Note that a representation of $\Delta_k$ as in \eqref{eq:Delta_k} is possible as it lies inside the convex hull $\mathcal{P}$ defined in \eqref{eq:DeltaBound}. Upon substituting (\ref{eq:Delta_k}) in \eqref{eq:s_k+1}, it readily follows that,
\begin{align}
\mathbf{S} \mathbf{s}_{k+1} = \sum_{j=1}^{n_\Delta}\mu_j \left(\mathbf{C}^{\Delta^j}_{\mathbf{s}} \mathbf{s}_k + \mathbf{C}^{\Delta^j}_{\mathbf{w}} w_k + \mathbf{S_u}\hat{\mathbf{u}}_{k+1}^j  \right), 
\end{align}
\begin{comment}













\end{comment}
and we obtain that
\begin{align}
   \mathbf{H}_{xu}\mathbf{S} \mathbf{s}_{k+1} &= \mathbf{H}_{xu} \sum_{j=1}^{n_\Delta}\mu_j \left(\mathbf{C}^j_{\mathbf{s}} \mathbf{s}_k +  \mathbf{C}^j_{\mathbf{w}} w_k + \mathbf{S_u}\hat{\mathbf{u}}_{k+1}^j\right)\nonumber\\
    & = \sum_{j=1}^{n_\Delta}\mu_j \mathbf{H}_{xu}  \left(\mathbf{C}^j_{\mathbf{s}} \mathbf{s}_k + \mathbf{S_u}\hat{\mathbf{u}}_{k+1}^j  + \mathbf{C}^j_{\mathbf{w}} w_k \right)\nonumber\\
    &\le \sum_{j=1}^{n_\Delta}\mu_j (\mathbf{b}-\mathbf{t})  = \mathbf{b}-\mathbf{t},\nonumber
\end{align}
where the inequality in the last step is obtained because \eqref{eq:NecSuff} is satisfied by the input sequences $\hat{\mathbf{u}}_{k+1}^j$.
Thus, \eqref{eq:FeasCond_k+1} admits a feasible solution and SRF holds true. 
\\
\textit{Necessity: }\\
Let the online optimization problem \eqref{eq:OnlOptProb} be recursively feasible. That is, let \eqref{eq:FeasCond_k+1} admit a feasible solution whenever \eqref{eq:FeasCond_k} admits one, for all realizations of $\Delta_k\in \mathcal{P}$ and $w_k \in \mathcal{W}$. 

Then, consider that for each $j \in \mathbb{N}_{1}^{n_\Delta}$, $\hat{\mathbf{u}}_{k+1}^j$ represents the feasible input sequences for \eqref{eq:FeasCond_k+1} when the perturbation $\Delta_k$ takes the value $\Delta^j$, and for $\mathbf{s}_k$ satisfying \eqref{eq:FeasCond_k} and $w_k \in \mathcal{W}$ . Then, using \eqref{eq:s_k+1}, \eqref{eq:FeasCond_k+1} can be written as
\begin{align}
\begin{split}
    \mathbf{H}_{xu}  (\mathbf{L} {+} \mathbf{S}_x B_p \Delta^j  D_{xu}  ) \mathbf{s}_k  +\mathbf{S}_u \hat{\mathbf{u}}_{k{+}1}^j + \quad & \nonumber \\
      \mathbf{S}_x (B_w {+} B_p \Delta^j D_w )w_k &\le \mathbf{b}-\mathbf{t} \\
     \implies \mathbf{H}_{xu}  \left(\mathbf{C}^{\Delta^j}_{\mathbf{s}} \mathbf{s}_k + \mathbf{C}^{\Delta^j}_{\mathbf{w}} w_k + \mathbf{S_u}\hat{\mathbf{u}}_{k+1}^j \right) &\le \mathbf{b}-\mathbf{t},
\end{split}
\end{align}
proving that \eqref{eq:NecSuff} is satisfied for all $j\in\mathbb{N}_{1}^{n_\Delta}$, and for $s_k$ satisfying \eqref{eq:FeasCond_k} and $w_k \in \mathcal{W}$, or compactly,
$ \forall \begin{bmatrix}
        \mathbf{s}_k ^\intercal & w_k^\intercal
    \end{bmatrix}^\intercal \in \mathbb{P}_1$.

\label{Thm:SuffCond}
    Consider the polytopes $\{\mathbb{P}_2^j\}_{j=1}^{n_{\Delta}}$  proposed in \eqref{eq:Poytope_P2j}.
    Then, Assumption \ref{Ass:RecFeas2} is satisfied if there exist feedback gains $K$, $\{ \{M_i^j\}_{j=i}^{n_{\Delta}} \}_{i=0}^{N-1}$ and $\{ \{ K_{i,\Delta}^j\}_{j=i}^{n_{\Delta}}\}_{i=0}^{N-1} $  such that
\begin{align}\label{eq:SuffCond}
     \mathbb{P}_1 \subseteq \mathbb{P}_2^j, \quad \forall j \in \mathbb{N}_1^{n_{\Delta}}.
\end{align}

In order for Assumption \ref{Ass:RecFeas2} to be satisfied, \eqref{eq:FeasCond_k+1} must be feasible for every $\mathbf{s}_k$ satisfying \eqref{eq:FeasCond_k}, $w_k\in \mathcal{W}$ and $\Delta_k \in \mathcal{P}$. 

Let $\Delta_k $ be defined as in \eqref{eq:Delta_k} and a candidate control input sequence be defined as $\hat{\mathbf{u}}_{k+1} =  \sum_{j=1}^{n_\Delta} \tau_j \hat{\mathbf{u}}_{k+1}^j$, where $\tau_j\in\mathbb{R}$ and  $\hat{\mathbf{u}}_{k+1}^j$ are parameterized according to \eqref{eq:InputParameterization}. 
Substituting this candidate sequence in \eqref{eq:s_k+1} and using \eqref{eq:InputParameterization} we obtain that
\begin{align}\label{eq:SuffCondPf1}
\mathbf{S} \mathbf{s}_{k+1} = \sum_{j=1}^{n_\Delta} \tau_j \bigg(\mathbf{C}_K^j s_k + \mathbf{C}_M^j w_k  \bigg).
\end{align}
Please see Appendix \ref{app: AppendixB} for algebraic details. Further, using \eqref{eq:SuffCondPf1}, it can be seen that
\begin{subequations}\label{eq:SuffCondPf2}
\begin{align}
   & H_{xu} \mathbf{S} \mathbf{s}_{k+1} = H_{xu}  \sum_{j=1}^{n_\Delta} \tau_j \bigg(\mathbf{C}_K^j s_k + \mathbf{C}_M^j w_k  \bigg) \label{eq:SuffCondPf2_1}\\
   &=    \sum_{j=1}^{n_\Delta} \tau_j H_{xu} \big( \mathbf{C}_K^j s_k + \mathbf{C}_M^j w_k  \big) \label{eq:SuffCondPf2_2}\\
   &\le  \sum_{j=1}^{n_\Delta} \tau_j (\mathbf{b}-\mathbf{t}) \le \mathbf{b}-\mathbf{t}, \label{eq:SuffCondPf2_3}
\end{align}
\end{subequations}
where \eqref{eq:SuffCondPf2_3} is obtained because any $\begin{bmatrix}
